using System;
using System.Collections;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
internal static partial class LyricsSource {
    internal sealed class Alternative {internal string Title,Artist,Album;internal int Duration;internal Result Result;public override string ToString(){return Title+" · "+Artist;}}
    internal static async Task<List<Alternative>> Alternatives(string query,CancellationToken token){var list=await Get("https://lrclib.net/api/search?q="+Escape(query),token).ConfigureAwait(false) as IList;return ParseAlternatives(list);}
    static List<Alternative> ParseAlternatives(IList list){var result=new List<Alternative>();if(list==null)return result;foreach(var item in list.Cast<object>().Take(40)){string synced=Convert.ToString(Catalog.Field(item,"syncedLyrics")),plain=Convert.ToString(Catalog.Field(item,"plainLyrics"));string text=string.IsNullOrWhiteSpace(synced)?plain:synced;if(string.IsNullOrWhiteSpace(text))continue;result.Add(new Alternative{Title=Convert.ToString(Catalog.Field(item,"trackName")),Artist=Convert.ToString(Catalog.Field(item,"artistName")),Album=Convert.ToString(Catalog.Field(item,"albumName")),Duration=(int)Convert.ToDouble(Catalog.Field(item,"duration")??0),Result=new Result{Text=text,Provider="LRCLIB · Your choice"}});}return result;}
    internal static async Task<List<Alternative>> AlternativesFor(Track song,string query,CancellationToken token){var result=await Alternatives(query,token).ConfigureAwait(false);if(result.Count>0||!string.Equals(query,(song.Title+" "+song.Artist).Trim(),StringComparison.OrdinalIgnoreCase))return result;string alias=await Catalog.NativeLyricArtist(song,token).ConfigureAwait(false);if(!string.IsNullOrWhiteSpace(alias)){var hits=await Get("https://lrclib.net/api/search?track_name="+Escape(song.Title)+"&artist_name="+Escape(alias),token).ConfigureAwait(false) as IList;result=ParseAlternatives(hits);}if(result.Count==0)result=await Alternatives(song.Title,token).ConfigureAwait(false);return result;}
}
internal partial class Player {
    static string LyricChoiceRoot {get{return Path.Combine(Catalog.Root,"data","lyric-choices");}}
    static string LyricChoicePath(Track t){using(var sha=SHA256.Create())return Path.Combine(LyricChoiceRoot,BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(Key(t)??"unknown"))).Replace("-","")+".json");}
    LyricsSource.Result SavedLyricChoice(Track t){try{string p=LyricChoicePath(t);if(File.Exists(p)&&new FileInfo(p).Length<2100000)return Catalog.Json().Deserialize<LyricsSource.Result>(File.ReadAllText(p));}catch(IOException){}catch(ArgumentException){}return null;}
    void SaveLyricChoice(Track t,LyricsSource.Result result){if(result==null||LyricsSource.Parse(result.Text).Count==0)throw new IOException("No lyric lines were found.");WriteAtomic(LyricChoicePath(t),Catalog.Json().Serialize(result));if(Key(t)==Key(Current)){lyricKey=null;LoadLyrics();}}
    void ShowLyricCorrection(){var song=Current;using(var d=DialogUI.Create("Choose the right lyrics","Saved for this recording. Timestamps are kept exactly as supplied.",680,610)){
        var search=DialogUI.Field(d,"Song or artist",song.Title+" "+song.Artist,24,112,490);var go=new SoftButton("Search",delegate{},true);go.SetBounds(530,140,126,38);d.Controls.Add(go);
        var list=new ListBox{Bounds=new Rectangle(24,195,632,280),BackColor=Theme.Ink,ForeColor=Theme.Paper,BorderStyle=BorderStyle.None,IntegralHeight=false,DrawMode=DrawMode.OwnerDrawFixed,ItemHeight=65,AccessibleName="Alternative lyric recordings"};d.Controls.Add(list);DarkScrollHost.Wrap(list).Visible=true;list.Visible=true;
        list.DrawItem+=delegate(object s,DrawItemEventArgs e){if(e.Index<0)return;var item=(LyricsSource.Alternative)list.Items[e.Index];var r=e.Bounds;r.Inflate(-2,-3);Fill(e.Graphics,r,12,(e.State&DrawItemState.Selected)!=0?Theme.Edge:Theme.Card);TextAt(e.Graphics,item.Title+" · "+item.Artist,new Rectangle(r.X+12,r.Y+6,r.Width-24,24),11,Theme.Paper,true);TextAt(e.Graphics,item.Album+" · "+Stamp(item.Duration*1000L)+(LyricsSource.Parse(item.Result.Text).Any(x=>x.Time>=0)?" · Synced":" · Plain lyrics"),new Rectangle(r.X+12,r.Y+32,r.Width-24,22),9,Theme.Muted);if((e.State&DrawItemState.Focus)!=0)e.DrawFocusRectangle();};
        var empty=new Surface{Bounds=new Rectangle(24,195,632,280),BackColor=Theme.Ink};empty.PaintSurface=delegate(Graphics g,Rectangle r){Fill(g,r,16,Theme.Card);Glyph(g,"\uE8D2",new Rectangle(r.Width/2-28,38,56,56),Theme.Peach,34);TextAt(g,"Find the matching recording",new Rectangle(20,116,r.Width-40,34),17,Theme.Paper,true,true);TextAt(g,"Compare the artist, album and duration before choosing.\nYour choice stays attached to this song.",new Rectangle(28,164,r.Width-56,65),11,Theme.Muted,false,true,true);};d.Controls.Add(empty);ScrollVisible(list,false);empty.BringToFront();d.Shown+=delegate{if(list.Items.Count==0)empty.BringToFront();};
        var note=DialogUI.Label(d,"Search for another recording or import your own LRC file.",24,487,632,27,10);CancellationTokenSource request=null;
        go.Click+=async delegate{if(request!=null)request.Cancel();var c=new CancellationTokenSource(TimeSpan.FromSeconds(20));request=c;go.Enabled=false;note.Text="Searching LRCLIB…";try{var results=await LyricsSource.AlternativesFor(song,search.Text.Trim(),c.Token);if(d.IsDisposed||c.IsCancellationRequested)return;empty.Visible=results.Count==0;ScrollVisible(list,results.Count>0);if(empty.Visible)empty.BringToFront();list.Items.Clear();foreach(var result in results)list.Items.Add(result);note.Text=results.Count==0?"No results. Try a shorter title or import an LRC file.":results.Count+" recordings · choose the matching artist and duration";}catch(Exception){if(!d.IsDisposed&&!c.IsCancellationRequested)note.Text="Search could not complete. Check your connection and retry.";}finally{if(!d.IsDisposed)go.Enabled=true;if(request==c)request=null;c.Dispose();}};
        var apply=new SoftButton("Use selected",delegate{var chosen=list.SelectedItem as LyricsSource.Alternative;if(chosen==null){note.Text="Choose a recording first.";return;}try{SaveLyricChoice(song,chosen.Result);d.Close();}catch(Exception ex){note.Text=ex.Message;}},true);apply.SetBounds(506,545,150,38);d.Controls.Add(apply);
        var import=new SoftButton("Import LRC",delegate{using(var file=new OpenFileDialog{Filter="Lyrics|*.lrc;*.txt;*.ttml"}){if(file.ShowDialog(d)!=DialogResult.OK)return;try{if(new FileInfo(file.FileName).Length>2000000)throw new IOException("Lyrics file is too large.");SaveLyricChoice(song,new LyricsSource.Result{Text=File.ReadAllText(file.FileName),Provider="Your lyrics file"});d.Close();}catch(Exception ex){note.Text=ex.Message;}}});import.SetBounds(24,545,140,38);d.Controls.Add(import);
        var reset=new SoftButton("Use automatic",delegate{string path=LyricChoicePath(song);if(File.Exists(path))File.Delete(path);if(Key(song)==Key(Current)){lyricKey=null;LoadLyrics(true);}d.Close();});reset.SetBounds(180,545,150,38);d.Controls.Add(reset);d.FormClosing+=delegate{if(request!=null)request.Cancel();};d.AcceptButton=go;d.ShowDialog(this);
    }}
}
